from lib import *
S = SS('h7')
steps = [
    step("键名大小写:客户端写 X-Request-ID 和 Authorization,线上的请求头是 authorization: Bearer tkn 和 x-request-id: abc-123(全部小写,与 content-type、user-agent、grpc-timeout 排在一起);服务端 metadata.FromIncomingContext 里取 x-request-id 得到 [abc-123]。metadata 的键在 gRPC 里不区分大小写,库统一转成小写。", t=tl(S(1)), done=lidx(S(1), '线上自定义头'), mark=lidx(S(1), '服务端 metadata'), b=bars([['客户端写的键', 2, 'X-Request-ID、Authorization'], ['线上的键(小写)', 2, 'x-request-id、authorization']], 3, done=[1], mark=[0]), kv=KV([['写 X-Request-ID', '线上 x-request-id'], ['服务端取', 'metadata.Get(\"x-request-id\")'], ['规则', '键不区分大小写,统一小写']], ['规则'])),
    step("哪些值能放:普通键 + 中文值,调用在客户端本地就失败,code=Internal,message “header key \\\"x-name\\\" contains value with non-printable ASCII characters”(含换行的值同样);以 -bin 结尾的键可以放任意字节:中文值在线上是 x-name-bin: 5byg5LiJ,字节 00 ff 10 80 是 x-raw-bin: AP8QgA(无填充的 base64);键里有空格,本地失败,message “contains illegal characters not in [0-9a-z-_.]”;键 X_Under_Score 被转成小写 x_under_score 照常发出;值为空字符串线上是 x-empty: (空值)。非 ASCII 的值要么用 -bin 键,要么自己编码。", t=tl(S(2)), done=lidx(S(2), '-bin 键 + 中文值'), mark=lidx(S(2), '普通键 + 中文值'), b=bars([['普通键 + 中文值', 13, 'Internal(本地失败)'], ['-bin 键 + 中文值', 0, 'OK'], ['键里有空格', 13, 'Internal(本地失败)'], ['-bin 随机字节', 0, 'OK']], 14, mark=[0, 2], done=[1, 3]), kv=KV([['普通键 + 非 ASCII 值', 'Internal,调用没发出去'], ['-bin 键', '任意字节,线上无填充 base64'], ['键允许的字符', '[0-9a-z-_.]']], ['-bin 键'])),
    step("库自己占用的头,通过 metadata 设置不会生效:设置 user-agent: my-client/2.0,线上仍是 user-agent: grpc-go/1.84.0;设置 content-type: application/json,线上仍是 application/grpc;设置 grpc-timeout: 1H,线上仍是库按 ctx 算的值;设置 grpc-encoding: gzip,线上没有 grpc-encoding。四种都不报错、被静默丢弃。改 User-Agent 要换别的办法:grpc-go 有 grpc.WithUserAgent 这个 dial 选项,我没有在这里验证它的线上值。", t=tl(S(3)), done=lidx(S(3), '设置 grpc-encoding'), mark=lidx(S(3), '设置 user-agent'), b=bars([['user-agent 设置后生效?', 0, '否'], ['content-type 设置后生效?', 0, '否'], ['grpc-timeout 设置后生效?', 0, '否'], ['grpc-encoding 设置后生效?', 0, '否']], 1, mark=[0, 1, 2, 3]), kv=KV([['user-agent', '线上仍是 grpc-go/1.84.0'], ['content-type / grpc-timeout / grpc-encoding', '被静默丢弃'], ['改 UA', 'grpc.WithUserAgent(未验证)']], ['改 UA'])),
    step("同一个键多个值:客户端 Pairs(\"x-tag\", \"a\", \"x-tag\", \"b\"),线上是两个独立的头行 x-tag: a 和 x-tag: b(没有合并成逗号),服务端 Get(\"x-tag\") 得到 [a b] 两个值。", t=tl(S(4)), done=lidx(S(4), '服务端看到 x-tag'), mark=lidx(S(4), '线上:'), b=bars([['线上头行数', 2, '2'], ['服务端取到的值个数', 2, '2']], 3, done=[0, 1]), kv=KV([['线上', 'x-tag: a 与 x-tag: b 两行'], ['服务端', 'Get 返回 [a b]'], ['合并', '没有合并成逗号']], ['线上'])),
    step("请求头总大小限制(服务端用默认设置):自定义头 1、8、64、512、4096、8192、15000、16000 KiB 都成功(code=OK);16400 KiB 失败,Unavailable,message “error reading from server: EOF”;20000 KiB 同样失败,message 是 connection reset by peer。分界在 16 MiB(16384 KiB)附近,与 grpc-go 源码 internal/transport/defaults.go 里 defaultServerMaxHeaderListSize = 16 << 20 一致:超过之后服务端直接断开连接,客户端看到的是 Unavailable,而不是一个说明“头太大”的明确错误。前面还有代理或网关时,它们的头限制通常小得多(nginx 默认 8 KiB 量级,见网关系列)。", t=tl(S(5)), done=lidx(S(5), '16000 KiB'), mark=lidx(S(5), '16400 KiB'), b=bars([['最大成功的头 KiB', 16000, '16000'], ['最小失败的头 KiB', 16400, '16400']], 16500, done=[0], mark=[1]), kv=KV([['成功', '1 KiB 到 16000 KiB'], ['失败', '16400 KiB 起:Unavailable,连接被断开'], ['注意', '错误信息不会告诉你是头太大']], ['注意'])),
    step("服务端的响应头与 trailers:Unary 里 grpc.SetHeader 设的 x-server: node-3 和 X-Mixed-Case: Value 与第一条响应一起发出,线上是 content-type: application/grpc、x-mixed-case: Value、x-server: node-3,客户端用 grpc.Header 取到;SetTrailer 的 x-late: t 出现在最后的 trailers(grpc-status: 0; grpc-message: ; x-late: t)。流式里 SendHeader 可以提前发:early 模式在 0.3 ms 就拿到了 x-early: 1;而先 Send 了一条消息再 SetHeader/SendHeader,服务端得到错误 “rpc error: code = Internal desc = transport: SendHeader called multiple times”,头没有发出去(客户端只看到 content-type)。响应头必须在第一条消息之前设置好。", t=tl(S(6)), done=lidx(S(6), '服务端 SendHeader 错误'), mark=lidx(S(6), '流式 early'), b=bars([['early:客户端拿到的自定义头', 1, 'x-early'], ['late:客户端拿到的自定义头', 0, '无']], 1.2, done=[0], mark=[1]), kv=KV([['Unary SetHeader', '与第一条响应一起发出'], ['流式 SendHeader', '可以提前发,0.3 ms 就到'], ['第一条消息之后再设', '失败:SendHeader called multiple times']], ['第一条消息之后再设'])),
]
A = mkarth('h7', 7, 'gRPC,metadata,请求头,-bin,响应头,trailers,Go,真实验证,动画演示',
    '实测 gRPC metadata:键统一小写;普通键只能放可打印 ASCII,-bin 键可放任意字节(线上无填充 base64);user-agent、content-type、grpc-timeout 等库占用的头被静默丢弃;同键多值是多行;头总大小 16 MiB 附近断开;响应头必须在第一条消息之前设置。',
    'metadata 就是 gRPC 的自定义请求头和响应头。键大小写怎么处理?中文能不能放?库占用的头能不能改?头多大会被拒?服务端什么时候能设响应头?这篇一项项抓包验证。',
    [('x-name-bin: 5byg5LiJ', '中文值放进 -bin 键时线上的样子(无填充 base64);放进普通键则调用本地失败'), ('16 MiB', '请求头总大小的分界:16000 KiB 成功,16400 KiB 起连接被断开'), ('SendHeader called multiple times', '先 Send 了消息再 SetHeader 时服务端得到的错误')],
    [('键', '<p>键统一小写,允许的字符是 [0-9a-z-_.]。大写的键(如 X-Request-ID)会被转成小写后发出。</p>'),
     ('值', '<p>普通键的值只能是可打印 ASCII,放中文或换行会让调用在客户端本地失败(Internal)。-bin 结尾的键可以放任意字节,线上用无填充的 base64。</p>'),
     ('保留头', '<p>user-agent、content-type、grpc-timeout、grpc-encoding 等库占用的头不能用 metadata 修改,设置了也被静默丢弃。要改 UA,grpc-go 有 grpc.WithUserAgent 选项(没有验证)。</p>'),
     ('多值', '<p>同一个键写多次,线上是多行头,服务端 Get 返回多个值。</p>'),
     ('大小', '<p>服务端默认接受约 16 MiB 的请求头;更大时连接被断开,客户端看到 Unavailable。路径上有代理时,代理的头限制通常小得多。</p>'),
     ('响应头与 trailers', '<p>Unary 里 SetHeader 与第一条响应一起发;流式里可以用 SendHeader 提前发。第一条消息发出后再设置响应头会失败。需要响应结束后才知道的信息,放 trailers(第 4 篇)。</p>')],
    steps,
    [ENV_H + '。线上头来自抓包代理解析的 HPACK;第五节只测了列出的几个大小,分界在 16000 与 16400 KiB 之间,没有进一步二分;服务端用默认 grpc.NewServer()',
     '没有验证:grpc-go 其它版本对保留头的处理;WithUserAgent 的实际线上值;服务端 MaxHeaderListSize 选项改小后的错误形式;客户端 MaxHeaderListSize 对响应头的限制;非 grpc-go 实现对 -bin 键与大小写的处理;超大头时 nginx 等中间层的行为'],
    'metadata')
